   ratified vault. ***
   anchor      : HUB_PRODUCT   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 2 emitted of 2 (one per source view AND run)
   runs        : 2 -- opus_health_legacy_v4, opus_health_v2
   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PRODUCT_HK
   hashdiff    : SAT_PRODUCT_HEALTH_MEMBERSHIP_RULES_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
*/

with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE))) as HUB_PRODUCT_HK
        , FF_DTLS_ONLY as FAMILY_FLOATER_DETAILS_ONLY_INDICATOR
        , cast(null as varchar) as SELF_MEMBER_EXCLUSION_ALLOWED_INDICATOR
        , cast(null as varchar) as MEMBER_PIN_CODE_VALIDATION_REQUIRED_INDICATOR
        , 'BJAZ_CTNGY_SCHEME_MST' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_mst') }}
    where (nullif(trim(SCHEME_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , cast(null as varchar) as FAMILY_FLOATER_DETAILS_ONLY_INDICATOR
        , SELF_EXCLUDE as SELF_MEMBER_EXCLUSION_ALLOWED_INDICATOR
        , PIN_CODE_VAL_YN as MEMBER_PIN_CODE_VALIDATION_REQUIRED_INDICATOR
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FAMILY_FLOATER_DETAILS_ONLY_INDICATOR end) as FAMILY_FLOATER_DETAILS_ONLY_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then SELF_MEMBER_EXCLUSION_ALLOWED_INDICATOR end) as SELF_MEMBER_EXCLUSION_ALLOWED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_PIN_CODE_VALIDATION_REQUIRED_INDICATOR end) as MEMBER_PIN_CODE_VALIDATION_REQUIRED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when FAMILY_FLOATER_DETAILS_ONLY_INDICATOR is not null or SELF_MEMBER_EXCLUSION_ALLOWED_INDICATOR is not null or MEMBER_PIN_CODE_VALIDATION_REQUIRED_INDICATOR is not null
                     then md5(upper(coalesce(cast(FAMILY_FLOATER_DETAILS_ONLY_INDICATOR as varchar), '') || '|' || coalesce(cast(SELF_MEMBER_EXCLUSION_ALLOWED_INDICATOR as varchar), '') || '|' || coalesce(cast(MEMBER_PIN_CODE_VALIDATION_REQUIRED_INDICATOR as varchar), '')))
                end as SAT_PRODUCT_HEALTH_MEMBERSHIP_RULES_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_HEALTH_MEMBERSHIP_RULES_HASHDIFF is not null
